using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;
using UnityEditor;
namespace ElswordPixel.Editor.BelowTerminalDiagnosticsV21 {
 public static class Worker {
  [Serializable] public sealed class Pin {public string path,sha256;}
  [Serializable] public sealed class Manifest {public string schema;public Pin bundle,model,rules,effects,sounds,mechanisms;public Pin[] modelSources,currentEntrySources;}
  [Serializable] public sealed class Model {public RoomDefinition[] rooms;}
  [Serializable] public sealed class Rules {public NpcDefinition[] definitions;}
  [Serializable] public sealed class State {
   public float time,width,right,exit,storedEdge,storedEdgeDifference,expressionEdgeDifference,reachable,contact,directHelperContact,sourceSolidEnd,sourceEndDifference,reachMarginDifference,gap,playerX,playerY,playerVy,gateDelay;
   public double extendedEdgeDifference;public string rightR,exitR,edgeR,sourceSolidEndR,reachableR,contactR;
   public int room,encounter,encounters,line,terminalId;public string roomId,title,world,encounterId,physicalState;public bool candidate,nativeTerrain,hasEncounters,lastEncounter,directionOne,grounded,gateOpen,conditionMet,sameDefinition,queryModelUnchanged;public GroundSurface actualSupport,terminalSolid;
  }
  [Serializable] public sealed class Case {public int hz,steps;public bool transitioned;public int finalRoom;public string failure;public State[] observations;}
  [Serializable] public sealed class Report {public string schema="below-UnityMono-full-original-room-terminal-diagnostic-v21",failure;public bool passed,diagnosticOnly=true,actualUnity=true,actualPlayMode=false,actualGameModelStep=true,naturalRoute=false,modelSourcesUnchanged,entrySourcesUnchanged;public int modelSourceCount,entrySourceCount,checks;public string fixtureBoundary="Actual Unity JsonUtility one-time parse of exact current Entry model/rules/effects/sounds/mechanisms. Full three rooms loaded; existing EnterRoom selects room1 original player spawn, no actor coordinate writes after load. All original NPC HP0/AIoff and player invincibility are explicit controlled fixture initialization to isolate already-cleared navigation. NativeNavigate emits ordinary move/jump/drop Input at30/60/120Hz; no production hooks/physics/data/scene mutations. Diagnostic completion is not natural route success.";public Case[] runs;}
  static Manifest manifest;static int checks;
  static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
  static readonly MethodInfo Enter=typeof(GameModel).GetMethod("EnterRoom",F),Contact=typeof(GameModel).GetMethod("EncounterExitContactX",F),Clamp=typeof(GameModel).GetMethod("NativeClampX",F),Helper=typeof(GameModel).GetMethod("ReconcileBelowDefaultEnvelopeExitV21",F);
  static void Check(bool good,string why){checks++;if(!good)throw new InvalidOperationException(why);}
  static string Hash(string path){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
  static string Read(Pin p){Check(p!=null&&File.Exists(p.path)&&Hash(p.path)==p.sha256,"Changed exact diagnostic input "+(p==null?"null":p.path));return File.ReadAllText(p.path);}
  static bool Sources(Pin[] pins){if(pins==null)return false;foreach(var p in pins)if(!File.Exists(p.path)||Hash(p.path)!=p.sha256)return false;return true;}
  static State Capture(GameModel g){var e=g.CurrentEncounter;float edge=e.rightX-.05f;var state=new State{time=g.elapsed,room=g.room,roomId=g.CurrentRoom.id,title=g.CurrentRoom.title,width=g.CurrentRoom.width,candidate=g.BelowTunnelCandidateEnabledV21,nativeTerrain=g.NativeTerrain,hasEncounters=g.HasEncounters,encounter=g.EncounterIndex,encounters=g.CurrentRoom.encounters.Length,encounterId=e.id,world=e.sourceWorldId,lastEncounter=g.EncounterIndex==g.CurrentRoom.encounters.Length-1,directionOne=e.direction==1,right=e.rightX,exit=e.exitX,storedEdge=edge,storedEdgeDifference=Math.Abs(e.exitX-edge),expressionEdgeDifference=Math.Abs(e.exitX-(e.rightX-.05f)),extendedEdgeDifference=Math.Abs((double)e.exitX-((double)e.rightX-(double).05f)),playerX=g.player.x,playerY=g.player.y,playerVy=g.player.vy,physicalState=g.player.state.ToString(),line=g.player.groundLine,grounded=g.Grounded(g.player),gateOpen=g.gateOpen,conditionMet=g.EncounterConditionMet,gateDelay=g.GateTransitionDelayRemaining,actualSupport=g.SurfaceBelow(g.player.x,g.player.y+.05f)};
   GroundSurface terminal=null;foreach(var s in g.CurrentRoom.surfaces)if(!s.platform&&(terminal==null||s.x2>terminal.x2))terminal=s;state.terminalSolid=terminal;state.terminalId=terminal==null?-1:terminal.id;state.sourceSolidEnd=terminal==null?float.NaN:terminal.x2;state.sourceEndDifference=Math.Abs(state.sourceSolidEnd-4711.08f);
   string before=JsonUtility.ToJson(g.player)+JsonUtility.ToJson(g.CurrentRoom);state.reachable=(float)Clamp.Invoke(g,new object[]{e.exitX});state.contact=(float)Contact.Invoke(g,new object[]{e});object[] args={e,e.exitX};Helper.Invoke(g,args);state.directHelperContact=(float)args[1];state.queryModelUnchanged=before==JsonUtility.ToJson(g.player)+JsonUtility.ToJson(g.CurrentRoom);state.sameDefinition=object.ReferenceEquals(e,g.CurrentEncounter);state.gap=e.exitX-state.reachable;state.reachMarginDifference=Math.Abs(state.reachable-(state.sourceSolidEnd-.03f));state.rightR=e.rightX.ToString("R");state.exitR=e.exitX.ToString("R");state.edgeR=edge.ToString("R");state.sourceSolidEndR=state.sourceSolidEnd.ToString("R");state.reachableR=state.reachable.ToString("R");state.contactR=state.contact.ToString("R");Check(state.queryModelUnchanged,"Read-only contact/helper diagnostic mutated model");return state;
  }
  static Case Probe(int hz){var run=new Case{hz=hz};var observations=new List<State>();try{
    // Exactly one JsonUtility parse, matching actual Entry rather than a second
    // serialize/parse of float fields that might itself change a final ULP.
    var rooms=JsonUtility.FromJson<Model>(Read(manifest.model)).rooms;for(int i=0;i<3;i++)rooms[i].title="Altera Below Tunnel / Source Room "+(i+1);var g=new GameModel();g.SetNpcDefinitions(JsonUtility.FromJson<Rules>(Read(manifest.rules)).definitions);g.SetNpcEffectDefinitions(JsonUtility.FromJson<NpcEffectDocument>(Read(manifest.effects)));g.SetNpcSoundDefinitions(JsonUtility.FromJson<NpcSoundDocument>(Read(manifest.sounds)));g.SetNpcMechanismDefinitions(JsonUtility.FromJson<NpcMechanismDocument>(Read(manifest.mechanisms)));g.SetRooms(rooms);Enter.Invoke(g,new object[]{1});foreach(var e in g.enemies){e.hp=0;e.aiEnabled=false;}g.player.invincible=100000;observations.Add(Capture(g));int lastEncounter=-1;bool endObserved=false;
    for(int i=0;i<hz*80;i++){float t=g.elapsed;var input=new Input{skill=-1};float x=(float)Clamp.Invoke(g,new object[]{g.CurrentEncounter.exitX});var support=g.SurfaceBelow(x,10000);Check(support!=null,"Actual source exit target has genuine support");if(!g.NativeNavigate(input,x,support.Y(x)))input.move=g.player.x<x?1:-1;g.Step(1f/hz,input);run.steps++;Check(g.elapsed>t&&!g.paused&&!g.victory,"Actual editor model Step advances");if(g.room!=1){run.transitioned=true;break;}if(g.EncounterIndex!=lastEncounter||Math.Abs(g.player.x-x)<2&&i%hz==0){observations.Add(Capture(g));lastEncounter=g.EncounterIndex;if(g.EncounterIndex==2&&Math.Abs(g.player.x-x)<2){if(endObserved&&i>hz*45)break;endObserved=true;}}}
    if(g.room==1)observations.Add(Capture(g));run.finalRoom=g.room;
   }catch(Exception ex){run.failure=ex.ToString();}run.observations=observations.ToArray();return run;
  }
  public static void Run(){var report=new Report();string output=Environment.GetEnvironmentVariable("EL_BELOW_GATE_DIAGNOSTIC_OUTPUT");try{string input=Environment.GetEnvironmentVariable("EL_BELOW_GATE_DIAGNOSTIC_MANIFEST");Check(!string.IsNullOrEmpty(input)&&!string.IsNullOrEmpty(output)&&!File.Exists(output),"Fresh explicit diagnostic input/output required");manifest=JsonUtility.FromJson<Manifest>(File.ReadAllText(input));Check(manifest.schema=="below-terminal-UnityMono-readonly-diagnostic-inputs-v21"&&manifest.modelSources.Length==73&&manifest.currentEntrySources.Length==30&&Sources(manifest.modelSources)&&Sources(manifest.currentEntrySources),"Exact current73model/30entry diagnostic source set");Read(manifest.bundle);report.runs=new[]{Probe(30),Probe(60),Probe(120)};report.modelSourceCount=manifest.modelSources.Length;report.entrySourceCount=manifest.currentEntrySources.Length;report.modelSourcesUnchanged=Sources(manifest.modelSources);report.entrySourcesUnchanged=Sources(manifest.currentEntrySources);report.passed=Array.TrueForAll(report.runs,r=>string.IsNullOrEmpty(r.failure)&&r.observations.Length>1)&&report.modelSourcesUnchanged&&report.entrySourcesUnchanged;}catch(Exception ex){report.failure=ex.ToString();}report.checks=checks;if(!string.IsNullOrEmpty(output))File.WriteAllText(output,JsonUtility.ToJson(report,true));Debug.Log("BELOW_TERMINAL_DIAGNOSTIC passed="+report.passed+" checks="+checks+" output="+output);EditorApplication.Exit(report.passed?0:1);}
 }
